namespace StokTakipUygulamasi;
internal sealed class frmStokuAzalanUrunler:Form
{
    readonly TextBox search;readonly NumericUpDown stock;readonly DataGridView grid;long selected;
    public frmStokuAzalanUrunler(){Ui.Setup(this,"STOKU AZALAN ÜRÜNLER",960,560);var root=UiLayout.Root(this,3);UiLayout.Row(root,0,52);UiLayout.Row(root,1,100);UiLayout.Row(root,2,100,false);UiLayout.Add(root,UiLayout.Heading("Stoku azalan ürünler",20),0,0);var filters=UiLayout.Card(3,1);UiLayout.Col(filters,0,45,false);UiLayout.Col(filters,1,30,false);UiLayout.Col(filters,2,25,false);UiLayout.Add(root,filters,0,1,margin:new Padding(0,0,0,12));search=UiLayout.Text();stock=new NumericUpDown{Maximum=int.MaxValue};UiLayout.Add(filters,UiLayout.Field("Ürün adı",search),0,0,margin:new Padding(0,0,6,0));UiLayout.Add(filters,UiLayout.Field("Stok adedi",stock),1,0,margin:new Padding(6,0,6,0));UiLayout.Add(filters,UiLayout.Button("Güncelle",UpdateStock,true),2,0,margin:new Padding(6,24,0,0));var list=UiLayout.Card(1,2);UiLayout.Row(list,0,38);UiLayout.Row(list,1,100,false);UiLayout.Add(list,UiLayout.Heading("20 adedin altındaki ürünler",13),0,0);grid=UiLayout.Grid();UiLayout.Add(list,grid,0,1);UiLayout.Add(root,list,0,2);grid.CellClick+=(_,e)=>{if(e.RowIndex>=0)Ui.Safe(()=>{selected=Ui.Selected(grid);stock.Value=Db.Number(grid.SelectedRows[0].Cells["Stok"].Value);});};search.TextChanged+=(_,_)=>Ui.Safe(Reload);Reload();}
    void Reload(){Ui.Bind(grid,Db.Query(Db.Products+" WHERE u.stok_adedi<20 AND (tr_contains(u.urun_adi,@p0) OR @p0='') ORDER BY u.stok_adedi,u.urun_adi",search.Text.Trim()));selected=0;stock.Value=0;}
    void UpdateStock(){if(selected==0)throw new InvalidOperationException("Bir ürün seçiniz.");Db.Exec("UPDATE urunler SET stok_adedi=@p0 WHERE urun_kodu=@p1",(long)stock.Value,selected);Reload();Ui.Info("Stok güncellendi.");}
}
